// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[80,"A",0,1],[96,"A",0,1],[112,"A",0,1],[128,"A",0,1],[144,"A",0,1],[160,"A",0,1],[176,"A",0,1],[192,"A",0,1],[208,"REST",0,1],[240,"REST",0,1],[256,"A",0,1],[272,"A",0,1],[288,"A",0,1],[304,"A",0,1],[320,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"B",0,1],[32,"B",0,1],[48,"B",0,1],[64,"B",0,1],[80,"REST",0,1],[208,"BRIDGE",0,1],[224,"BRIDGE",0,1],[240,"RUN",0,1],[256,"REST",0,1],[320,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[80,"REST",0,1],[208,"REST",0,1],[240,"REST",0,1],[256,"HARMONY",0,1],[320,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- keygen ------------------------------------------------------------------------------------
const track0 = {
  color: '#7dffb0',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["K = \\tfrac{1}{256}\\big\\lfloor 256\\,\\LP_{9000}\\,\\Pi_{w(T)}(g)\\big\\rceil,\\quad w = 0.31 + 0.19\\sin 2\\pi\\,0.7T,\\quad g = f\\cdot 2^{0.15\\min(1, (t - 0.15)^+/0.2)\\sin(2\\pi\\cdot 6T)/12}","\\text{пинг-понг через 3/16, вторая октава } 0.25\\,\\Pi_{w}(2g)"],
  audio({ bpm }) {
    const sec = 60 / bpm, lp = filter('lp'), gate = smooth(3), glide = smooth(10), echo = delay({ time: sec * 0.75, feedback: 0.38, wet: 0.3 }), verb = reverb({ room: 0.92, damp: 0.3, wet: 0.3 })
    let ph = 0, ph2 = 0, n = 0
    return x => {
      const m = leadAt(x), T = x * sec, held = m ? m.τ * sec : 0
      if (m) n = m.n
      const g = hz(glide(n), C4) * 2 ** ((0.15 * Math.min(1, Math.max(0, held - 0.15) / 0.2) * sin(TAU * 6 * T)) / 12), w = 0.31 + 0.19 * sin(TAU * 0.7 * T)
      ph = (ph + g / 44100) % 1; ph2 = (ph2 + (2 * g) / 44100) % 1
      const s = (ph < w ? 1 : -1) + 0.25 * (ph2 < w ? 1 : -1), y = Math.round(256 * lp(s, 9000) / 1.25) / 256
      const out = 0.24 * gate(m && m.u < 0.9 ? 1 : 0) * y
      const [l, r] = echo(out, 0)
      return verb(l + 0.2 * r, r + 0.6 * out)
    }
  },
}

// ---- pulse -------------------------------------------------------------------------------------
const track1 = {
  color: '#c9a2ff',
  graph: x => { const m = lead2At(x); return m ? 1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = lead2At(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["\\Pi_{0.25}(f) = \\tfrac12\\big(\\saw(\\varphi) - \\saw(\\varphi + 0.25)\\big),\\quad y = \\vol(1 - 0.35\\min(1, t/0.4))\\cdot\\Pi_{0.25}","f = 261.63\\cdot 2^{(n + 0.2\\sin 2\\pi\\,5.5T)/12}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = pulse(0.25), lp = filter('lp'), gate = smooth(1.5), echo = delay({ time: sec * 0.75, feedback: 0.4, wet: 0.3 }), verb = reverb({ room: 0.7, wet: 0.2 })
    let n = 0
    return x => {
      const m = lead2At(x), t = x * sec, held = m ? m.τ * sec : 0
      if (m) n = m.n
      const vib = held > 0.25 ? 0.2 * sin(TAU * 5.5 * t) : 0
      const g = gate(m && m.u < 0.9 ? vol4(1 - 0.35 * Math.min(1, held / 0.4)) : 0)
      return verb(...echo(...pan(0.405 * g * lp(p(hz(n + vib, C4)), 9000), -0.3)))
    }
  },
}

