const track3 = {
  color: '#c9a227',
  graph: x => (chordAt(x) && energy(x) >= 0 ? chordAt(x)[3].map(n => -1 + (n - 48) / 20) : null),
  midi: x => (chordAt(x) && energy(x) >= 0 && mod(x, 4) < 3.9 ? chordAt(x)[3] : []),
  formula: ["O = \\Rev\\sum_{j}\\sum_{s \\in \\{1, 2, 3, 4\\}} a_s\\sin\\big(2\\pi\\,s f_j\\,(1 \\pm 0.0008)\\,t\\big) + \\text{«чифф»}\\ 0.25e^{-t/0.05}\\BP_{3f}\\eta\\quad\\text{— регистры } 8^\\prime, 4^\\prime, 2\\tfrac23^\\prime, 2^\\prime"],
  audio() {
    const o = organ({ voices: 4, gain: 0.1 }), level = smooth(200), verb = reverb({ room: 0.94, damp: 0.35, wet: 0.5 })
    return x => {
      const c = chordAt(x), e = energy(x), a = level(c && e >= 0 ? [0.6, 0.75, 0.9, 1][e] : 0)
      const [l, r] = o(c && e >= 0 && mod(x, 4) < 3.95 ? c[3].map(n => hz(n - 60, C4)) : [])
      return verb(a * l, a * r)
    }
  },
}

// ---- choirpad ----------------------------------------------------------------------------------
const track4 = {
  color: '#c9b6ff',
  graph: x => (padOn(x) ? chordAt(x)[3].map(n => -1.7 + (n - 48) / 30) : null),
  midi: x => (padOn(x) && mod(x, 4) < 3.9 ? chordAt(x)[3] : []),
  formula: ["Ch = \\Rev\\sum_{j} \\sum_{i=1}^{3} \\tfrac{G_i}{Q_i}\\BP_{F_i}\\,\\saw(f_j),\\quad F = \\text{«а»}"],
  audio() {
    const vs = [0, 1, 2, 3].map(j => voice({ size: 1 - 0.04 * j, breath: 0.05 })), level = smooth(400), verb = reverb({ room: 0.92, wet: 0.55 })
    return x => {
      const c = chordAt(x), a = level(padOn(x) ? 1 : 0)
      let l = 0, r = 0
      vs.forEach((v, j) => { const y = v(hz((c ? c[3][j % c[3].length] : 60) - 60, C4) * (1 + 0.002 * j), VOWELS.a, 1); l += y * (j % 2 ? 0.4 : 0.6); r += y * (j % 2 ? 0.6 : 0.4) })
      return verb(0.336 * a * l, 0.336 * a * r)
    }
  },
}

